export function SwitchCard({
  leading,
  trailing,
  trailingOn,
  trailingOff,
  label,
  description,
  error,
  className,
  switchSize = "md",
  variant = "minimal",
  disabled,
  checked,
  defaultChecked = false,
  onCheckedChange,
  onChange,
  id,
  labelPosition: _labelPosition,
  fullWidth: _fullWidth,
  containerClassName: _containerClassName,
  controlClassName: _controlClassName,
  labelClassName: _labelClassName,
  descriptionClassName: _descriptionClassName,
  ...props
}: SwitchCardProps) {
  const reactId = React.useId();
  const switchId = id ?? `ui-switch-card-${reactId}`;
  const descriptionId = description ? `${switchId}-description` : undefined;
  const errorId = error ? `${switchId}-error` : undefined;
  const isControlled = checked !== undefined;
  const [uncontrolledChecked, setUncontrolledChecked] =
    React.useState(defaultChecked);
  const isChecked = isControlled ? checked : uncontrolledChecked;
  const trailingLabel =
    trailingOn !== undefined || trailingOff !== undefined
      ? isChecked
        ? trailingOn
        : trailingOff
      : trailing;
  const describedBy =
    [errorId, descriptionId].filter(Boolean).join(" ") || undefined;
  const hasAnimatedTrailing =
    trailingOn !== undefined || trailingOff !== undefined;
  const [trailingSwapping, setTrailingSwapping] = React.useState(false);
  const prevCheckedRef = React.useRef(isChecked);

  React.useEffect(() => {
    ensureSwitchStyles();
  }, []);

  React.useEffect(() => {
    if (!hasAnimatedTrailing) {
      prevCheckedRef.current = isChecked;
      return;
    }
    if (prevCheckedRef.current === isChecked) return;
    prevCheckedRef.current = isChecked;
    setTrailingSwapping(true);
    const timeoutId = window.setTimeout(() => setTrailingSwapping(false), 220);
    return () => window.clearTimeout(timeoutId);
  }, [hasAnimatedTrailing, isChecked]);

  const handleChange = React.useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const nextChecked = event.currentTarget.checked;
      if (!isControlled) setUncontrolledChecked(nextChecked);
      onCheckedChange?.(nextChecked, event);
      onChange?.(event);
    },
    [isControlled, onChange, onCheckedChange],
  );

  return (
    <label
      data-slot="switch"
      data-state={isChecked ? "checked" : "unchecked"}
      data-disabled={disabled ? "" : undefined}
      data-error={error ? "" : undefined}
      htmlFor={switchId}
      className={cn(
        "group/switch flex min-h-16 w-full cursor-pointer select-none items-center gap-3.5 px-4 py-3",
        "transition-[background-color] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none",
        !disabled &&
          "hover:bg-[color-mix(in_srgb,var(--foreground)_2%,var(--background))]",
        "data-[state=checked]:bg-[color-mix(in_srgb,var(--foreground)_2.5%,var(--background))]",
        disabled && "cursor-not-allowed opacity-50 hover:bg-transparent",
        className,
      )}
    >
      <input
        id={switchId}
        type="checkbox"
        role="switch"
        checked={isChecked}
        disabled={disabled}
        aria-checked={isChecked}
        aria-invalid={error ? true : undefined}
        aria-describedby={describedBy}
        onChange={handleChange}
        className="peer sr-only"
        {...props}
      />

      {leading ? (
        <span
          className={cn(
            "switch-card-icon grid size-9 shrink-0 place-items-center rounded-lg",
            "border border-[var(--border)]",
            "bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))]",
            "text-[var(--muted-foreground)]",
            "transition-[border-color,background-color,color] duration-[220ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none",
            "[&_svg]:size-[17px]",
            "group-data-[state=checked]/switch:border-[color-mix(in_srgb,var(--foreground)_12%,transparent)]",
            "group-data-[state=checked]/switch:bg-[color-mix(in_srgb,var(--foreground)_7%,var(--background))]",
            "group-data-[state=checked]/switch:text-[var(--foreground)]",
            disabled && "opacity-80",
          )}
        >
          {leading}
        </span>
      ) : null}

      <span className="min-w-0 flex-1">
        {label ? (
          <span
            className={cn(
              "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
              labelSizes[switchSize],
              disabled && "text-[var(--muted-foreground)]",
            )}
          >
            {label}
          </span>
        ) : null}
        {description ? (
          <span
            id={descriptionId}
            className="mt-0.5 line-clamp-2 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]"
          >
            {description}
          </span>
        ) : null}
        {error ? (
          <span
            id={errorId}
            className="mt-1 block text-[12px] leading-5 text-red-600 dark:text-red-400"
          >
            {error}
          </span>
        ) : null}
      </span>

      <span className="flex shrink-0 items-center gap-2.5 pl-1">
        {trailingLabel ? (
          <span
            aria-live="polite"
            data-slot="switch-card-trailing"
            data-swapping={trailingSwapping ? "true" : undefined}
            className={cn(
              "inline-flex min-w-[3.25rem] items-center justify-center rounded-md border border-[var(--border)]",
              "bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] px-1.5 py-0.5",
              "text-[10px] font-medium tracking-[0.01em] text-[var(--muted-foreground)]",
              "group-data-[state=checked]/switch:border-[color-mix(in_srgb,var(--foreground)_10%,transparent)]",
              "group-data-[state=checked]/switch:text-[var(--foreground)]",
            )}
          >
            {trailingLabel}
          </span>
        ) : null}
        <SwitchControl
          checked={isChecked}
          disabled={disabled}
          error={error}
          switchSize={switchSize}
          variant={variant}
        />
      </span>
    </label>
  );
}
